/* The three diagrams below use only the current native task parameters.
 * Rendering never selects a task, changes its answer, or writes progress.
 * Step counts stay identical to the native solution for board action replay. */
const Oge18TaskDiagram = (() => {
  'use strict';
  const supported = new Set(['segCmp', 'areaPar', 'circRatio']);
  const ink = '#25382c', grid = '#d6ddcf', blue = '#216b9c', orange = '#a7500a';
  const green = '#216342', pale = '#e8f0e9', warm = '#f5dfbf';
  const fmt = n => String(Number(n.toFixed(8))).replace('.', ',');
  const cells = n => n === 1 ? 'клетка' : n >= 2 && n <= 4 ? 'клетки' : 'клеток';
  function decompose(n) {
    for (let a = Math.floor(Math.sqrt(n)); a >= 0; a--) {
      const b = Math.round(Math.sqrt(n - a*a));
      if (a*a + b*b === n) return [a, b];
    }
    return null;
  }
  function supports(task) {
    if (!task || !supported.has(task.sub) || !Array.isArray(task.p)) return false;
    const p = task.p;
    if (!p.every(Number.isFinite)) return false;
    if (task.sub === 'segCmp') return p.length === 2 && p[0] > 0 && p[1] > p[0] && p.every(Number.isInteger);
    if (task.sub === 'areaPar') return p.length === 3 && p[0] > 0 && p[1] > 0 && p[2] >= 0 && p[2] <= p[0] && p.every(Number.isInteger);
    return p.length === 2 && p[0] > 0 && p[1] > p[0] && p.every(Number.isInteger) && p.every(n => decompose(n));
  }
  function actions(task) {
    if (!supports(task)) return [];
    return task.sub === 'segCmp'
      ? ['Выделить отрезки и посчитать клетки', 'Сравнить длины']
      : task.sub === 'areaPar'
        ? ['Показать основание и высоту', 'Составить прямоугольник']
        : ['Найти радиусы по клеткам', 'Сравнить квадраты радиусов', 'Вычислить отношение площадей'];
  }
  function radiusWords(n, name) {
    const radius = Math.sqrt(n), [up, right] = decompose(n);
    if (Number.isInteger(radius)) return `${name}: от центра до края — <strong>${radius} ${cells(radius)}</strong>.`;
    return `${name}: по клеткам <strong>${right} вправо и ${up} вверх</strong>; сам радиус идёт наискось.`;
  }
  function squareWords(n, symbol) {
    const radius = Math.sqrt(n), [up, right] = decompose(n);
    return Number.isInteger(radius)
      ? `${symbol}² = ${radius} × ${radius} = <strong>${n}</strong>`
      : `${symbol}² = ${up}² + ${right}² = <strong>${n}</strong>`;
  }
  function steps(task) {
    if (!supports(task)) return [];
    const p = task.p;
    if (task.sub === 'segCmp') return [
      `Считаем клетки вдоль AC: <strong>AM = ${p[0]}</strong>, <strong>MC = ${p[1]}</strong>. Каждый короткий штрих отделяет одну клетку.`,
      `Чтобы узнать, во сколько раз MC длиннее AM, делим длины: <strong>${p[1]} : ${p[0]} = ${fmt(p[1]/p[0])}</strong>.`
    ];
    if (task.sub === 'areaPar') return [
      `Основание — <strong>${p[0]} ${cells(p[0])}</strong>. Высота — <strong>${p[1]} ${cells(p[1])}</strong> по вертикали между основаниями. Прямой угол отмечен квадратиком.`,
      `Перенесли выделенный треугольник вправо — получили прямоугольник. Площадь сохранилась: <strong>${p[0]} × ${p[1]} = ${p[0]*p[1]}</strong>.`
    ];
    const diagonal = !Number.isInteger(Math.sqrt(p[0])) || !Number.isInteger(Math.sqrt(p[1]));
    return [
      radiusWords(p[0], 'Малый круг') + '<br>' + radiusWords(p[1], 'Большой круг'),
      `${diagonal ? 'Для наклонного радиуса используем теорему Пифагора. ' : ''}Квадраты на тех же радиусах:<br>${squareWords(p[0], 'r')}; ${squareWords(p[1], 'R')}.`,
      `Площадь круга равна π · радиус². При делении двух площадей π сокращается: <strong>${p[1]} : ${p[0]} = ${fmt(p[1]/p[0])}</strong>. Ответ: <strong>${fmt(p[1]/p[0])}</strong>.`
    ];
  }
  function render(task, step, requestedWidth) {
    if (!supports(task)) return task && typeof task.fig === 'string' ? task.fig : '';
    const width = Math.max(240, Math.min(1000, Number.isFinite(requestedWidth) && requestedWidth > 0 ? requestedWidth : 640));
    const stage = Math.max(0, Math.min(actions(task).length, Math.floor(Number(step)) || 0));
    const p = task.p;
    let W, H, foot = 96, top = 30;
    if (task.sub === 'segCmp') { W = p[0]+p[1]+2; H = Math.min(5, Math.max(3, Math.round((p[0]+p[1])/2)))+2; }
    else if (task.sub === 'areaPar') { W = p[0]+p[2]+2; H = p[1]+2; foot = 60; }
    else { W = Math.ceil(Math.sqrt(p[0]))*2 + Math.ceil(Math.sqrt(p[1]))*2 + 3; H = Math.ceil(Math.sqrt(p[1]))*2+2; top = 48; foot = stage >= 3 ? 100 : 64; }
    const unit = Math.min(46, (width-48)/W);
    const offset = (width-W*unit)/2;
    const height = top+H*unit+foot;
    const x = v => offset+v*unit, y = v => top+(H-v)*unit;
    const xy = point => `${x(point[0])},${y(point[1])}`;
    const attr = role => role ? ` data-oge18-role="${role}"` : '';
    const label = (X,Y,value,anchor='middle') => `<text x="${X}" y="${Y}" text-anchor="${anchor}" fill="${ink}" font-family="system-ui,sans-serif" font-size="20" font-weight="600">${value}</text>`;
    const line = (a,b,color=ink,weight=2,role='',dash='') => `<line${attr(role)} x1="${x(a[0])}" y1="${y(a[1])}" x2="${x(b[0])}" y2="${y(b[1])}" stroke="${color}" stroke-width="${weight}"${dash ? ` stroke-dasharray="${dash}"` : ''}/>`;
    const polygon = (points,fill=pale,stroke=ink,role='',opacity=1,dash='') => `<polygon${attr(role)} points="${points.map(xy).join(' ')}" fill="${fill}" fill-opacity="${opacity}" stroke="${stroke}" stroke-width="2"${dash ? ` stroke-dasharray="${dash}"` : ''}/>`;
    const dot = (point,role='') => `<circle${attr(role)} cx="${x(point[0])}" cy="${y(point[1])}" r="4" fill="${ink}"/>`;
    const ticks = (a,b,color,role) => {
      const horizontal = a[1] === b[1];
      const length = Math.abs(horizontal ? b[0]-a[0] : b[1]-a[1]);
      let result = line(a,b,color,5,role);
      for (let n=0;n<=length;n++) {
        const X = x(horizontal ? Math.min(a[0],b[0])+n : a[0]);
        const Y = y(horizontal ? a[1] : Math.min(a[1],b[1])+n);
        result += `<line x1="${X-(horizontal?0:4)}" y1="${Y-(horizontal?4:0)}" x2="${X+(horizontal?0:4)}" y2="${Y+(horizontal?4:0)}" stroke="${color}" stroke-width="2"/>`;
      }
      return result;
    };
    let body = '';
    for(let gx=0;gx<=W;gx++) body += line([gx,0],[gx,H],grid,1);
    for(let gy=0;gy<=H;gy++) body += line([0,gy],[W,gy],grid,1);
    let description;
    if (task.sub === 'segCmp') {
      const [am,mc] = p, ac=am+mc, h=H-2;
      const A=[1,1], M=[1+am,1], C=[1+ac,1], B=[1+Math.round(ac*.4),1+h];
      body += polygon([A,B,C],pale,ink,'shape');
